import pytest

from ghidra_manager.errors import ManagerError
from ghidra_manager.mcp import (
    DEFAULT_PORT,
    discover_instances,
    probe_analysis,
    probe_server,
    validate_base_port,
)


def test_discovery_accepts_wrapped_and_direct_records() -> None:
    records: dict[int, object] = {
        DEFAULT_PORT + 2: {
            "data": {
                "pid": 42,
                "project": "second\nproject",
                "programs": [
                    {"name": "OPEN.EXE", "open": True},
                    {"name": "CLOSED.EXE", "open": False},
                ],
            }
        },
        DEFAULT_PORT: {"pid": 7, "project": "first"},
        DEFAULT_PORT + 1: {"pid": "invalid"},
    }

    instances = discover_instances(DEFAULT_PORT, fetch=records.get)

    assert [(item.port, item.pid, item.project) for item in instances] == [
        (DEFAULT_PORT, 7, "first"),
        (DEFAULT_PORT + 2, 42, "second project"),
    ]
    assert instances[1].programs == ("OPEN.EXE",)


@pytest.mark.parametrize("value", [0, -1, 65521])
def test_invalid_base_port(value: int) -> None:
    with pytest.raises(ManagerError):
        validate_base_port(value)


def test_server_and_analysis_probes() -> None:
    responses: dict[str, object] = {
        "/get_version": {
            "plugin_version": "5.14.2",
            "ghidra_version": "12.1.2",
            "java_version": "21.0.11",
            "endpoint_count": 206,
        },
        "/analysis_status": {
            "name": "DEMO.EXE",
            "analyzing": False,
            "analyzed": True,
            "function_count": 123,
        },
    }

    def fetch(_port, path, _params):  # type: ignore[no-untyped-def]
        return responses[path]

    server = probe_server(DEFAULT_PORT, fetch=fetch)
    analysis = probe_analysis(DEFAULT_PORT, "DEMO.EXE", fetch=fetch)

    assert server is not None and server.endpoint_count == 206
    assert analysis is not None and analysis.function_count == 123

"""GhidraMCP instance discovery."""

from __future__ import annotations

import json
import urllib.error
import urllib.parse
import urllib.request
from collections.abc import Callable, Mapping
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from typing import Any

from ghidra_manager.errors import ManagerError

DEFAULT_PORT = 8089
PORT_RANGE = 16
Fetch = Callable[[int], object | None]
EndpointFetch = Callable[[int, str, Mapping[str, str] | None], object | None]


@dataclass(frozen=True, slots=True, order=True)
class Instance:
    port: int
    pid: int
    project: str
    programs: tuple[str, ...] = ()

    @property
    def url(self) -> str:
        return f"http://127.0.0.1:{self.port}"


@dataclass(frozen=True, slots=True)
class ServerInfo:
    plugin_version: str
    ghidra_version: str
    java_version: str
    endpoint_count: int


@dataclass(frozen=True, slots=True)
class AnalysisStatus:
    program: str
    analyzing: bool
    analyzed: bool
    function_count: int


def validate_base_port(value: int) -> int:
    if value <= 0 or value > 65535 - PORT_RANGE + 1:
        raise ManagerError("Base port leaves no room for the 16-port fallback range")
    return value


def _fetch_instance(port: int) -> object | None:
    request = urllib.request.Request(
        f"http://127.0.0.1:{port}/mcp/instance_info",
        headers={"Accept": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=1) as response:
            value: object = json.load(response)
            return value
    except (OSError, TimeoutError, ValueError, urllib.error.URLError):
        return None


def _fetch_endpoint(
    port: int, path: str, params: Mapping[str, str] | None = None
) -> object | None:
    query = f"?{urllib.parse.urlencode(params)}" if params else ""
    request = urllib.request.Request(
        f"http://127.0.0.1:{port}{path}{query}",
        headers={"Accept": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=2) as response:
            value: object = json.load(response)
            return value
    except (OSError, TimeoutError, ValueError, urllib.error.URLError):
        return None


def _parse_instance(port: int, value: object | None) -> Instance | None:
    if not isinstance(value, dict):
        return None
    record: Any = value.get("data", value)
    if not isinstance(record, dict) or not isinstance(record.get("pid"), int):
        return None
    project = (
        str(record.get("project") or "unknown")
        .replace("\t", " ")
        .replace("\r", " ")
        .replace("\n", " ")
    )
    raw_programs = record.get("programs")
    programs = (
        tuple(
            str(item["name"])
            for item in raw_programs
            if isinstance(item, dict)
            and item.get("name")
            and item.get("open", True) is True
        )
        if isinstance(raw_programs, list)
        else ()
    )
    return Instance(port=port, pid=record["pid"], project=project, programs=programs)


def discover_instances(
    base_port: int = DEFAULT_PORT, *, fetch: Fetch = _fetch_instance
) -> list[Instance]:
    """Probe GhidraMCP's configured fallback range and return valid instances."""
    validate_base_port(base_port)
    ports = range(base_port, base_port + PORT_RANGE)
    with ThreadPoolExecutor(max_workers=PORT_RANGE) as executor:
        values = executor.map(fetch, ports)
    return sorted(
        instance
        for port, value in zip(ports, values, strict=True)
        if (instance := _parse_instance(port, value)) is not None
    )


def probe_server(port: int, *, fetch: EndpointFetch = _fetch_endpoint) -> ServerInfo | None:
    value = fetch(port, "/get_version", None)
    if not isinstance(value, dict):
        return None
    try:
        return ServerInfo(
            plugin_version=str(value["plugin_version"]),
            ghidra_version=str(value["ghidra_version"]),
            java_version=str(value["java_version"]),
            endpoint_count=int(value["endpoint_count"]),
        )
    except (KeyError, TypeError, ValueError):
        return None


def probe_analysis(
    port: int,
    program: str,
    *,
    fetch: EndpointFetch = _fetch_endpoint,
) -> AnalysisStatus | None:
    value = fetch(port, "/analysis_status", {"program": program})
    if not isinstance(value, dict):
        return None
    try:
        return AnalysisStatus(
            program=str(value["name"]),
            analyzing=bool(value["analyzing"]),
            analyzed=bool(value["analyzed"]),
            function_count=int(value["function_count"]),
        )
    except (KeyError, TypeError, ValueError):
        return None

"""Typed manager state and release metadata."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

DoctorLevel = Literal["ok", "warning", "error"]


@dataclass(frozen=True, slots=True)
class DoctorCheck:
    name: str
    level: DoctorLevel
    detail: str


@dataclass(frozen=True, slots=True)
class PluginMetadata:
    plugin_id: str
    version: str
    tag: str
    commit: str
    extension_name: str
    extension_root: str
    artifact: str
    digest: str
    runtime_files: tuple[tuple[str, str], ...] = ()

    def runtime_file(self, name: str) -> str | None:
        return dict(self.runtime_files).get(name)


@dataclass(frozen=True, slots=True)
class PairMetadata:
    pair_id: str
    ghidra_version: str
    ghidra_tag: str
    plugins: tuple[PluginMetadata, ...] = ()

    def plugin(self, plugin_id: str) -> PluginMetadata | None:
        return next((plugin for plugin in self.plugins if plugin.plugin_id == plugin_id), None)


@dataclass(frozen=True, slots=True)
class ManagerState:
    current: str | None = None
    previous: str | None = None
    schema_version: int = 2


@dataclass(frozen=True, slots=True)
class ReleaseAsset:
    name: str
    url: str
    digest: str


@dataclass(frozen=True, slots=True)
class ResolvedGhidra:
    version: str
    tag: str
    asset: ReleaseAsset


@dataclass(frozen=True, slots=True)
class ResolvedPluginSource:
    plugin_id: str
    version: str
    tag: str
    commit: str
    archive_url: str
    runtime_assets: tuple[tuple[str, ReleaseAsset], ...] = ()


@dataclass(frozen=True, slots=True)
class ResolvedPair:
    ghidra_version: str
    ghidra_latest_version: str
    ghidra_tag: str
    ghidra_asset: ReleaseAsset
    mcp_version: str
    mcp_tag: str
    mcp_extension: ReleaseAsset
    mcp_bridge: ReleaseAsset
    mcp_requirements: ReleaseAsset

    @property
    def pair_id(self) -> str:
        return f"ghidra-{self.ghidra_version}__mcp-{self.mcp_version}"
